-- Phase 2.3: reusable questionnaires, immutable order snapshots, and field-associated uploads.
CREATE TABLE IF NOT EXISTS questionnaire_templates (
 id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, internal_description TEXT NULL, status VARCHAR(50) NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL, updated_at DATETIME NULL,
 UNIQUE KEY uq_questionnaire_templates_title (title), INDEX idx_questionnaire_templates_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS questionnaire_fields (
 id INT AUTO_INCREMENT PRIMARY KEY, questionnaire_template_id INT NOT NULL, field_key VARCHAR(100) NOT NULL, field_type VARCHAR(50) NOT NULL, label TEXT NOT NULL, admin_label VARCHAR(255) NULL, help_text TEXT NULL, placeholder VARCHAR(500) NULL, options_json JSON NULL, validation_json JSON NULL, is_required TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NULL,
 UNIQUE KEY uq_questionnaire_field_key (questionnaire_template_id,field_key), INDEX idx_questionnaire_fields_active_order (questionnaire_template_id,is_active,sort_order,id), CONSTRAINT fk_questionnaire_fields_template FOREIGN KEY (questionnaire_template_id) REFERENCES questionnaire_templates(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE products ADD COLUMN questionnaire_template_id INT NULL AFTER contract_template_id, ADD INDEX idx_products_questionnaire_template (questionnaire_template_id), ADD CONSTRAINT fk_products_questionnaire_template FOREIGN KEY (questionnaire_template_id) REFERENCES questionnaire_templates(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS order_questionnaire_snapshots (
 id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, questionnaire_template_id INT NULL, questionnaire_title VARCHAR(255) NOT NULL, questionnaire_snapshot_json JSON NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_order_questionnaire_snapshot_order (order_id), INDEX idx_oqs_template (questionnaire_template_id), CONSTRAINT fk_oqs_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_oqs_template FOREIGN KEY (questionnaire_template_id) REFERENCES questionnaire_templates(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_questionnaire_answers (
 id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, questionnaire_snapshot_id INT NOT NULL, field_key VARCHAR(100) NOT NULL, field_type VARCHAR(50) NOT NULL, question_label TEXT NOT NULL, answer_text MEDIUMTEXT NULL, answer_json JSON NULL, sort_order INT NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY uq_oqa_snapshot_field (questionnaire_snapshot_id,field_key), INDEX idx_oqa_order_order (order_id,sort_order,id), CONSTRAINT fk_oqa_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_oqa_snapshot FOREIGN KEY (questionnaire_snapshot_id) REFERENCES order_questionnaire_snapshots(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE order_uploads ADD COLUMN questionnaire_field_key VARCHAR(100) NULL AFTER upload_type, ADD COLUMN questionnaire_answer_id INT NULL AFTER questionnaire_field_key, ADD INDEX idx_order_uploads_questionnaire (order_id,questionnaire_field_key), ADD CONSTRAINT fk_order_uploads_questionnaire_answer FOREIGN KEY (questionnaire_answer_id) REFERENCES order_questionnaire_answers(id) ON DELETE SET NULL;
